#!/usr/bin/env python3
"""Round 94b tiles (27 September): fur farms worldwide (fur_farms.py), natural disasters of every kind (natural_hazards.py), dead zones and deep-sea mining (oceans.py), and a read-only count of Nusantara's other concessions by kind (concession_probe.py). Upload to the culprits-tiles-more repo's patches folder. Safe to run twice."""
import base64, os, pathlib, sys
FILES = {
    'scripts/fur_farms.py': """""",
    'scripts/natural_hazards.py': """""",
    'scripts/oceans.py': """""",
    'scripts/concession_probe.py': """""",
}
if not os.path.isdir("scripts"):
    sys.exit("Run this from the culprits-tiles-more folder.")
n = 0
for name, b in FILES.items():
    p, data = pathlib.Path(name), base64.b64decode(b)
    if p.exists() and p.read_bytes() == data:
        continue
    p.write_bytes(data); n += 1; print("written:", name)
print(f"{n} file(s) changed" if n else "Already applied. Nothing changed.")
